template.script:
(function () {
    var pend = null;
    document.addEventListener('click', function (e) {
        var b = e.target.closest('.prod-del-btn');
        if (!b) { return; }
        pend = b.closest('form');
        var modo = b.getAttribute('data-modo') || 'eliminar';
        var nombre = b.getAttribute('data-nombre') || '';
        var t = document.getElementById('prodConfirmTitle');
        var x = document.getElementById('prodConfirmTxt');
        var ok = document.getElementById('prodConfirmOk');
        if (modo === 'archivar') {
            t.textContent = 'Archivar producto';
            x.innerHTML = 'Este producto ya tiene ventas, así que no se elimina: se archivará y saldrá del marketplace. Podrás reactivarlo después. «»';
            ok.textContent = 'Archivar';
            ok.classList.remove('s-btn-danger'); ok.classList.add('s-btn-primary');
        } else {
            t.textContent = 'Eliminar producto';
            x.innerHTML = '¿Seguro que quieres eliminar «»? Saldrá de tu lista y pasará al histórico; no volverás a verlo ni podrás reactivarlo.';
            ok.textContent = 'Eliminar';
            ok.classList.remove('s-btn-primary'); ok.classList.add('s-btn-danger');
        }
        var s = x.querySelector('strong'); if (s) { s.textContent = nombre; }
        document.getElementById('prodConfirmModal').classList.add('open');
    });
    window.prodCloseConfirm = function () {
        document.getElementById('prodConfirmModal').classList.remove('open');
        pend = null;
    };
    window.prodDoConfirm = function () { if (pend) { pend.submit(); } };
    document.getElementById('prodConfirmModal').addEventListener('click', function (e) {
        if (e.target === this) { window.prodCloseConfirm(); }
    });
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') { window.prodCloseConfirm(); }
    });
})();

(function () {

  // ======= GALERÍA (nuevo producto) =======
  function initNewGallery(){
    const addBtn = document.getElementById("np_add_btn");
    const addInput = document.getElementById("np_add_input");
    const thumbs = document.getElementById("np_thumbs");

    const mainImg = document.getElementById("np_main_img");
    const placeholder = document.getElementById("np_main_placeholder");

    const prevBtn = document.getElementById("np_prev_btn");
    const nextBtn = document.getElementById("np_next_btn");

    if (!addBtn || !addInput || !thumbs || !mainImg || !placeholder) return;

    function getThumbImgs(){
      return Array.from(thumbs.querySelectorAll("img.np-thumb"));
    }

    function reindex(){
      getThumbImgs().forEach((img, idx) => img.dataset.index = String(idx));
    }

    function showArrowsIfNeeded(){
      const n = getThumbImgs().length;
      if (!prevBtn || !nextBtn) return;
      const show = n > 1;
      prevBtn.style.display = show ? "flex" : "none";
      nextBtn.style.display = show ? "flex" : "none";
    }

function setActive(idx){
  const list = getThumbImgs();
  const t = list[idx];
  if (!t) return;

  // ✅ poner imagen en main
  mainImg.src = t.dataset.url;
  mainImg.dataset.index = String(idx);

  // ✅ mostrar img / ocultar placeholder SIEMPRE

  placeholder.style.setProperty("display", "none", "important");
        mainImg.style.setProperty("display", "block", "important");


  list.forEach((el, i) => {
    if (i === idx) {
      el.style.border = "2px solid rgba(18,62,92,.55)";
      el.style.boxShadow = "0 8px 18px rgba(18,62,92,.15)";
    } else {
      el.style.border = "1px solid rgba(0,0,0,.12)";
      el.style.boxShadow = "none";
    }
  });

  showArrowsIfNeeded();
}


 function go(delta) {
      const thumbs = getThumbImgs();
      const n = thumbs.length;
      if (!n) return;

      // si main es div "Sin fotos", no hay navegación
      if (!mainImg.tagName || mainImg.tagName.toLowerCase() !== "img") return;

      const current = parseInt((mainImg.dataset && mainImg.dataset.index) || "0", 10);
      const next = (current + delta + n) % n;
      setActive(next);
    }

    if (prevBtn) prevBtn.addEventListener("click", () => go(-1));
    if (nextBtn) nextBtn.addEventListener("click", () => go(1));

    addBtn.addEventListener("click", () => addInput.click());

    addInput.addEventListener("change", () => {
      const files = Array.from(addInput.files || []);
      if (!files.length) return;

      // Insertar thumbs antes del botón +
      const beforeNode = addBtn;

      files.forEach((f) => {
        if (!f.type || !f.type.startsWith("image/")) return;
        const url = URL.createObjectURL(f);

        const img = document.createElement("img");
        img.className = "np-thumb";
        img.dataset.url = url;
        img.alt = "Miniatura";
        img.src = url;

        thumbs.insertBefore(img, beforeNode);
      });

      reindex();

      // activar la primera si no había ninguna
      const list = getThumbImgs();
      if (list.length) setActive(0);
    });

    // click miniaturas
    thumbs.addEventListener("click", (e) => {
      const t = e.target.closest("img.np-thumb");
      if (!t) return;
      const idx = parseInt(t.dataset.index || "0", 10);
      setActive(idx);
    });
  }

  // ======= CERTIFICADOS =======
  let prodCertIndex = 5000;   // base alta: no choca con los índices de filas de usuario
  let prodCertCache = null;

  async function fetchProductCerts() {
    if (prodCertCache) return prodCertCache;

    const payload = { jsonrpc: "2.0", method: "call", params: {}, id: Date.now() };
    const r = await fetch("/marketplace/certificados_producto", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      credentials: "same-origin",
    });

    const data = await r.json();
    if (data.error) throw new Error(data.error.data?.message || data.error.message || "Error RPC");
    prodCertCache = data.result || [];
    return prodCertCache;
  }

  function buildOptions(certs) {
    const out = ['<option value="">Seleccione…</option>'];
    certs.forEach(c => {
      const issuer = (c.issuer || "").replace(/"/g, "&quot;");
      out.push(`<option value="${c.id}" data-issuer="${issuer}">${c.name}</option>`);
    });
    return out.join("");
  }

  function rowHtml(idx, optionsHtml) {
    return `
      <div class="card border-0 mb-3 mp-cert-row">
        <div class="card-body p-3">
          <div class="d-flex justify-content-between align-items-center mb-3">
            <div style="font-weight:800;"><i class="fa fa-certificate me-1" style="color:var(--shrimp-teal);"></i> Nuevo certificado</div>
            <button type="button" class="s-btn s-btn-danger btn-sm delBtn"><i class="fa fa-trash-o me-1"></i> Eliminar</button>
          </div>

          <div class="row g-3">
            <div class="col-md-5">
              <label class="form-label" style="font-weight:800; font-size:13px;">Certificado</label>
              <select class="form-select certSel" name="prod_cert_${idx}_id" required>
                ${optionsHtml}
              </select>
            </div>

            <div class="col-md-3">
              <label class="form-label" style="font-weight:800; font-size:13px;">Entidad</label>
              <input class="form-control issuer" type="text" readonly placeholder="Entidad"/>
            </div>

            <div class="col-md-4">
              <label class="form-label" style="font-weight:800; font-size:13px;">N°</label>
              <input class="form-control" name="prod_cert_${idx}_number" placeholder="Opcional"/>
            </div>

            <div class="col-md-4">
              <label class="form-label" style="font-weight:800; font-size:13px;">Emisión</label>
              <input class="form-control" type="date" name="prod_cert_${idx}_issue_date"/>
            </div>

            <div class="col-md-4">
              <label class="form-label" style="font-weight:800; font-size:13px;">Expira</label>
              <input class="form-control" type="date" name="prod_cert_${idx}_expiry_date"/>
            </div>

            <div class="col-md-4">
              <label class="form-label" style="font-weight:800; font-size:13px;">Archivo <span class="text-danger">*</span></label>
              <input class="form-control" type="file" name="prod_cert_${idx}_file" required accept="image/*,application/pdf"/>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  async function addRow() {
    const container = document.getElementById("prodCertContainer");
    if (!container) return;

    const certs = await fetchProductCerts();
    const idx = prodCertIndex++;

    const wrapper = document.createElement("div");
    wrapper.innerHTML = rowHtml(idx, buildOptions(certs));
    const card = wrapper.firstElementChild;
    // Los nuevos certificados se agregan al inicio de la lista.
    container.insertBefore(card, container.firstChild);

    const sel = card.querySelector(".certSel");
    const issuerInp = card.querySelector(".issuer");

    sel.addEventListener("change", () => {
      const opt = sel.selectedOptions[0];
      issuerInp.value = opt ? (opt.getAttribute("data-issuer") || "") : "";
    });

    card.querySelector(".delBtn").addEventListener("click", () => card.remove());
  }

  function initCerts() {
    var addBtn = document.querySelector(".shrimpAddProdCert");
    var body = document.getElementById("prodCertBody");
    var modal = document.getElementById("certEditorModal");
    if (!modal || !body) { return; }

    var certMode = "new";
    var editingRow = null;

    function refreshEmpty(){
      var e = document.getElementById("prodCertEmpty");
      if(!e) return;
      var any=false;
      body.querySelectorAll(".pcert-row").forEach(function(r){ if(r.style.display!=="none") any=true; });
      e.style.display = any ? "none" : "";
    }
    function recreateFile(){
      var wrap=document.getElementById("ce_file_wrap");
      wrap.innerHTML="";
      var f=document.createElement("input");
      f.type="file"; f.id="ce_file"; f.className="form-control"; f.accept="image/*,application/pdf";
      wrap.appendChild(f);
      return f;
    }
    async function openModal(mode,row){
      certMode=mode; editingRow=row||null;
      var sel=document.getElementById("ce_cert");
      var issuer=document.getElementById("ce_issuer");
      try{ sel.innerHTML=buildOptions(await fetchProductCerts()); }catch(e){ sel.innerHTML='<option value="">(error)</option>'; }
      function syncIssuer(){ var o=sel.selectedOptions[0]; issuer.value=o?(o.getAttribute("data-issuer")||""):""; }
      sel.onchange=syncIssuer;
      recreateFile();
      document.getElementById("ce_err").style.display="none";
      var req=document.getElementById("ce_file_req");
      var hint=document.getElementById("ce_file_hint");
      if(mode==="edit" && row){
        document.getElementById("certEditorTitle").textContent="Editar certificado";
        sel.value=row.getAttribute("data-cert")||""; sel.disabled=true; syncIssuer();
        document.getElementById("ce_number").value=row.getAttribute("data-number")||"";
        document.getElementById("ce_issue").value=row.getAttribute("data-issue")||"";
        document.getElementById("ce_expiry").value=row.getAttribute("data-expiry")||"";
        req.style.display="none"; hint.textContent="Deja vacío para conservar el archivo actual.";
      } else {
        document.getElementById("certEditorTitle").textContent="Agregar certificado";
        sel.disabled=false; sel.value=""; syncIssuer();
        document.getElementById("ce_number").value="";
        document.getElementById("ce_issue").value="";
        document.getElementById("ce_expiry").value="";
        req.style.display=""; hint.textContent="";
      }
      modal.classList.add("open");
    }
    function closeModal(){ modal.classList.remove("open"); editingRow=null; }
    function save(){
      var sel=document.getElementById("ce_cert");
      var num=document.getElementById("ce_number").value;
      var iss=document.getElementById("ce_issue").value;
      var exp=document.getElementById("ce_expiry").value;
      var fileInp=document.getElementById("ce_file");
      var err=document.getElementById("ce_err");
      function showErr(m){ err.textContent=m; err.style.display=""; }
      var hasFile=fileInp && fileInp.files && fileInp.files.length;
      if(certMode==="new"){
        if(!sel.value){ showErr("Elige un certificado."); return; }
        if(!hasFile){ showErr("Adjunta el archivo."); return; }
        var idx=prodCertIndex++;
        var fname="prod_cert_"+idx+"_file";
        var certName=sel.selectedOptions[0].textContent;
        var issuerV=sel.selectedOptions[0].getAttribute("data-issuer")||"";
        var tr=document.createElement("tr");
        tr.className="pcert-row"; tr.setAttribute("data-kind","nuevo");
        tr.setAttribute("data-cert",sel.value);
        tr.setAttribute("data-number",num); tr.setAttribute("data-issue",iss); tr.setAttribute("data-expiry",exp);
        tr.setAttribute("data-fname",fname);
        tr.innerHTML='<td class="pc-name"></td><td class="pc-issuer"></td><td class="pc-number"></td><td class="pc-issue"></td><td class="pc-expiry"></td><td><span class="s-badge">Nuevo</span></td><td class="text-end pcert-actions"><input type="hidden" name="prod_cert_'+idx+'_id"/><input type="hidden" class="ei-number" name="prod_cert_'+idx+'_number"/><input type="hidden" class="ei-issue" name="prod_cert_'+idx+'_issue_date"/><input type="hidden" class="ei-expiry" name="prod_cert_'+idx+'_expiry_date"/><span class="ei-file-slot"></span><button type="button" class="s-btn s-btn-ghost btn-sm pcert-edit" title="Editar"><i class="fa fa-pencil"></i></button><button type="button" class="s-btn s-btn-danger btn-sm pcert-del" title="Quitar"><i class="fa fa-trash"></i></button></td>';
        tr.querySelector(".pc-name").textContent=certName;
        tr.querySelector(".pc-issuer").textContent=issuerV||"—";
        tr.querySelector(".pc-number").textContent=num||"—";
        tr.querySelector(".pc-issue").textContent=iss||"—";
        tr.querySelector(".pc-expiry").textContent=exp||"—";
        tr.querySelector('input[name="prod_cert_'+idx+'_id"]').value=sel.value;
        tr.querySelector(".ei-number").value=num;
        tr.querySelector(".ei-issue").value=iss;
        tr.querySelector(".ei-expiry").value=exp;
        fileInp.name=fname; fileInp.id=""; fileInp.classList.add("d-none");
        tr.querySelector(".ei-file-slot").appendChild(fileInp);
        body.appendChild(tr);
      } else if(editingRow){
        var row=editingRow;
        row.setAttribute("data-number",num); row.setAttribute("data-issue",iss); row.setAttribute("data-expiry",exp);
        row.querySelector(".pc-number").textContent=num||"—";
        row.querySelector(".pc-issue").textContent=iss||"—";
        row.querySelector(".pc-expiry").textContent=exp||"—";
        var a=row.querySelector(".ei-number"); if(a) a.value=num;
        var b=row.querySelector(".ei-issue"); if(b) b.value=iss;
        var c=row.querySelector(".ei-expiry"); if(c) c.value=exp;
        if(hasFile){
          var slot=row.querySelector(".ei-file-slot");
          if(slot){ slot.innerHTML=""; fileInp.name=row.getAttribute("data-fname")||fileInp.name; fileInp.id=""; fileInp.classList.add("d-none"); slot.appendChild(fileInp); }
        }
      }
      closeModal(); refreshEmpty();
    }
    // Borrado con confirmación por modal (no inmediato).
    var delModal=document.getElementById("certDelModal");
    var pendingDel=null;
    function aplicarBorrado(row){
      var flag=row.querySelector(".pcert-remove-flag");
      if(flag){ flag.checked=true; row.style.display="none"; } else { row.remove(); }
      refreshEmpty();
    }
    if(addBtn){ addBtn.addEventListener("click", function(){ openModal("new"); }); }
    body.addEventListener("click", function(e){
      var ed=e.target.closest(".pcert-edit");
      if(ed){ openModal("edit", ed.closest(".pcert-row")); return; }
      var del=e.target.closest(".pcert-del");
      if(del){
        pendingDel=del.closest(".pcert-row");
        if(delModal){ delModal.classList.add("open"); } else { aplicarBorrado(pendingDel); }
        return;
      }
    });
    var cdOk=document.getElementById("cd_ok");
    if(cdOk){ cdOk.addEventListener("click", function(){ if(pendingDel){ aplicarBorrado(pendingDel); } if(delModal){ delModal.classList.remove("open"); } pendingDel=null; }); }
    var cdCancel=document.getElementById("cd_cancel");
    if(cdCancel){ cdCancel.addEventListener("click", function(){ if(delModal){ delModal.classList.remove("open"); } pendingDel=null; }); }
    if(delModal){ delModal.addEventListener("click", function(e){ if(e.target===delModal){ delModal.classList.remove("open"); pendingDel=null; } }); }
    var cancel=document.getElementById("ce_cancel"); if(cancel){ cancel.addEventListener("click", closeModal); }
    var saveBtn=document.getElementById("ce_save"); if(saveBtn){ saveBtn.addEventListener("click", save); }
    modal.addEventListener("click", function(e){ if(e.target===modal){ closeModal(); } });
    refreshEmpty();
  }

  function initPondFilter(){
    var fac = document.getElementById("originFacility");
    var pond = document.getElementById("originPond");
    if(!fac || !pond) return;
    var opts = Array.prototype.slice.call(pond.querySelectorAll("option[value]")).filter(function(o){ return o.value; });
    function apply(){
      var f = fac.value;
      var currentOk = false;
      opts.forEach(function(o){
        var of = o.getAttribute("data-facility") || "";
        // Muestra piscinas de la instalación elegida; si no hay instalación, muéstralas todas.
        var show = !f || of === f;
        o.hidden = !show;
        o.disabled = !show;
        if(show && o.selected) currentOk = true;
      });
      if(!currentOk){ pond.value = ""; }
    }
    fac.addEventListener("change", apply);
    apply();
  }

  function initProdCertDelete(){
    document.querySelectorAll(".prod-cert-del-btn").forEach(function(btn){
      btn.addEventListener("click", function(){
        var card = btn.closest(".prod-cert-card");
        if(!card) return;
        var flag = card.querySelector(".prod-cert-del-flag");
        if(flag){ flag.checked = true; }
        card.style.display = "none";
      });
    });
  }

  function initSizeFilter(){
    var pres = document.getElementById("prodPresentation");
    var size = document.getElementById("prodSizeGrade");
    if(!pres || !size) return;
    var opts = Array.prototype.slice.call(size.querySelectorAll("option[value]")).filter(function(o){ return o.value; });
    function apply(){
      var p = pres.value;
      var ok = false;
      opts.forEach(function(o){
        var op = o.getAttribute("data-presentation") || "";
        var show = !!p && op === p;   // sin presentación no hay tallas válidas
        o.hidden = !show; o.disabled = !show;
        if(show && o.selected) ok = true;
      });
      if(!ok){ size.value = ""; }
    }
    pres.addEventListener("change", apply);
    apply();
  }

  function initExistingPhotos(){
    var wrap = document.getElementById("np_thumbs");
    if(!wrap) return;
    var mainImg = document.getElementById("np_main_img");
    var ph = document.getElementById("np_main_placeholder");
    function showMain(url){
      if(mainImg){ mainImg.src = url; mainImg.style.display = "block"; }
      if(ph){ ph.style.display = "none"; }
    }
    var exist = wrap.querySelectorAll(".np-exist");
    // Al cargar, si no hay foto nueva en el visor, muestra la primera existente.
    if(exist.length && mainImg && mainImg.style.display === "none"){
      showMain(exist[0].getAttribute("data-full"));
    }
    wrap.addEventListener("click", function(e){
      var del = e.target.closest(".np-exist-del");
      if(del){
        e.preventDefault();
        var box = del.closest(".np-exist");
        var cb = box.querySelector("input[type=checkbox]");
        if(cb){ cb.checked = true; }
        box.remove();
        return;
      }
      var thumb = e.target.closest(".np-exist");
      if(thumb){ showMain(thumb.getAttribute("data-full")); }
    });
  }

  function init(){
    initNewGallery();
    initCerts();
    initPondFilter();
    initProdCertDelete();
    initSizeFilter();
    initExistingPhotos();
  }

  document.addEventListener("DOMContentLoaded", init);

})();

(function () {
function initMarketplaceGallery() {
const mainImg = document.getElementById("mp_main_img");
const thumbsWrap = document.getElementById("mp_thumbs");
const prevBtn = document.getElementById("mp_prev_btn");
const nextBtn = document.getElementById("mp_next_btn");

if (!mainImg || !thumbsWrap) return;

function getThumbs() {
return Array.from(thumbsWrap.querySelectorAll(".mp-thumb"));
}

function setActive(idx) {
const thumbs = getThumbs();
const t = thumbs[idx];
if (!t) return;

mainImg.src = t.dataset.url;
mainImg.dataset.index = String(idx);

thumbs.forEach((el, i) => {
if (i === idx) {
el.style.border = "2px solid rgba(18,62,92,.55)";
el.style.boxShadow = "0 8px 18px rgba(18,62,92,.15)";
} else {
el.style.border = "1px solid rgba(0,0,0,.12)";
el.style.boxShadow = "none";
}
});
}

thumbsWrap.addEventListener("click", function (e) {
const thumb = e.target.closest(".mp-thumb");
if (!thumb) return;

const idx = parseInt(thumb.dataset.index || "0", 10);
setActive(idx);
});

function go(delta) {
const thumbs = getThumbs();
const n = thumbs.length;
if (!n) return;

const current = parseInt(mainImg.dataset.index || "0", 10);
const next = (current + delta + n) % n;
setActive(next);
}

if (prevBtn) prevBtn.addEventListener("click", () => go(-1));
if (nextBtn) nextBtn.addEventListener("click", () => go(1));

setActive(0);
}

if (document.readyState === "loading") {
document.addEventListener("DOMContentLoaded", initMarketplaceGallery);
} else {
initMarketplaceGallery();
}
})();
